package config

import (
	"bufio"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// systemdDirectives reads testdata/systemd-directives.txt, generated by
// tools/systemddirectives from systemd's own parsing table.
func systemdDirectives(t *testing.T) [][2]string {
	t.Helper()
	f, err := os.Open("testdata/systemd-directives.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	var out [][2]string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		sec, key, ok := strings.Cut(line, " ")
		if !ok {
			t.Fatalf("malformed line %q", line)
		}
		out = append(out, [2]string{sec, key})
	}
	if len(out) < 400 {
		t.Fatalf("only %d directives in testdata/systemd-directives.txt — regenerate it", len(out))
	}
	return out
}

// sampleSystemdValue is a plausible value for a directive, enough to
// reach its case in the loader: the classification check looks at which
// warning comes back, not at the mapping itself.
func sampleSystemdValue(key string) string {
	switch {
	case strings.HasPrefix(key, "Exec"):
		return "/bin/true"
	case strings.HasPrefix(key, "Condition") || strings.HasPrefix(key, "Assert"):
		return "/etc/hostname"
	case strings.HasSuffix(key, "Sec") || strings.HasSuffix(key, "USec"):
		return "5"
	case strings.HasPrefix(key, "Limit"):
		return "1024"
	}
	return "yes"
}

// convertOne loads a unit holding one assignment of key in section.
func convertOne(t *testing.T, dir, section, key, val string) ([]SystemdWarning, error) {
	t.Helper()
	body := "[Service]\nExecStart=/bin/sleep 1\n"
	if section == "Service" {
		body += key + "=" + val + "\n"
	} else {
		body = "[" + section + "]\n" + key + "=" + val + "\n" + body
	}
	p := filepath.Join(dir, "probe.service")
	if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
		t.Fatal(err)
	}
	_, warns, err := ConvertSystemdUnit(p)
	return warns, err
}

// sdPending are directives the loader does not answer for yet. It only
// shrinks: TestEverySystemdDirectiveIsClassified fails for a directive
// missing from it that is unclassified, and for one listed here that is
// classified now, so it cannot hide a regression or go stale.
var sdPending = map[string]bool{}

// TestEverySystemdDirectiveIsClassified: every directive systemd defines
// for a .service unit is mapped, handled by a bespoke case, listed with a
// reason in sdNoEquivalent, or ignored on purpose. None falls through to
// the generic "not mapped" warning, which on a unit loaded directly is a
// log line nobody reads while the directive is dropped.
func TestEverySystemdDirectiveIsClassified(t *testing.T) {
	dir := t.TempDir()
	var unclassified, stale []string
	for _, d := range systemdDirectives(t) {
		sec, key := d[0], d[1]
		warns, _ := convertOne(t, dir, sec, key, sampleSystemdValue(key))
		generic := false
		for _, w := range warns {
			if strings.Contains(w.Msg, "` not mapped") {
				generic = true
			}
		}
		id := sec + "." + key
		switch {
		case generic && !sdPending[id]:
			unclassified = append(unclassified, id)
		case !generic && sdPending[id]:
			stale = append(stale, id)
		}
	}
	sort.Strings(unclassified)
	sort.Strings(stale)
	if len(unclassified) > 0 {
		t.Errorf("%d systemd directives fall through to \"not mapped\"; map them, or list them in sdNoEquivalent / sdIgnored with the reason:\n  %s",
			len(unclassified), strings.Join(unclassified, "\n  "))
	}
	if len(stale) > 0 {
		t.Errorf("%d directives are classified now; remove them from sdPending:\n  %s", len(stale), strings.Join(stale, "\n  "))
	}
}

// TestRegistryKeysAreSlinitSettings: every rule names a setting slinit's
// parser knows, so a typo in a table is caught here rather than as a
// "converted to a service slinit cannot load" error on some machine.
func TestRegistryKeysAreSlinitSettings(t *testing.T) {
	for _, tab := range []map[string]sdRule{sdServiceRules, sdUnitRules} {
		for sd, r := range tab {
			if r.custom != nil {
				continue
			}
			err := validateSlinitSetting(r.key, "")
			if err != nil && strings.Contains(err.Error(), "unknown setting") {
				t.Errorf("%s maps to %q, which slinit does not know", sd, r.key)
			}
		}
	}
}

// TestRegistryAndSwitchDoNotOverlap: a directive is classified once. A
// gap or an ignore entry for a directive that also has a rule would never
// be reached, and reads as a decision that was not taken.
func TestRegistryAndSwitchDoNotOverlap(t *testing.T) {
	check := func(section string, rules map[string]sdRule, gaps map[string]sdGap, ignored map[string]string) {
		for k := range gaps {
			if _, ok := rules[k]; ok {
				t.Errorf("[%s] %s has a rule and an sdNoEquivalent entry", section, k)
			}
			if _, ok := ignored[k]; ok {
				t.Errorf("[%s] %s is both a gap and ignored", section, k)
			}
		}
		for k := range ignored {
			if _, ok := rules[k]; ok {
				t.Errorf("[%s] %s has a rule and an sdIgnored entry", section, k)
			}
		}
	}
	check("Service", sdServiceRules, sdServiceNoEquivalent, sdServiceIgnored)
	check("Unit", sdUnitRules, sdUnitNoEquivalent, sdUnitIgnored)
}

func TestApplyRuleSemantics(t *testing.T) {
	mapped := func(cfg *SystemdConfig, key string) []string {
		var out []string
		for _, kv := range cfg.mapped {
			if kv.key == key {
				out = append(out, kv.value)
			}
		}
		return out
	}

	t.Run("scalar: the last assignment wins", func(t *testing.T) {
		cfg := &SystemdConfig{}
		r := sdRule{key: "nice"}
		cfg.applyRule("Service", "Nice", "5", r)
		cfg.applyRule("Service", "Nice", "-3", r)
		if got := mapped(cfg, "nice"); len(got) != 1 || got[0] != "-3" {
			t.Fatalf("nice = %q, want one assignment, -3", got)
		}
	})

	t.Run("list: assignments add up, an empty one resets", func(t *testing.T) {
		cfg := &SystemdConfig{}
		r := sdRule{key: "supplementary-groups", shape: sdList}
		cfg.applyRule("Service", "SupplementaryGroups", "a b", r)
		cfg.applyRule("Service", "SupplementaryGroups", "c", r)
		if got := mapped(cfg, "supplementary-groups"); len(got) != 1 || got[0] != "a b c" {
			t.Fatalf("after two assignments: %q, want [\"a b c\"]", got)
		}
		cfg.applyRule("Service", "SupplementaryGroups", "", r)
		cfg.applyRule("Service", "SupplementaryGroups", "d", r)
		if got := mapped(cfg, "supplementary-groups"); len(got) != 1 || got[0] != "d" {
			t.Fatalf("after a reset: %q, want [\"d\"]", got)
		}
	})

	t.Run("behaviour: a value slinit refuses is dropped with a warning", func(t *testing.T) {
		cfg := &SystemdConfig{}
		w := cfg.applyRule("Service", "Nice", "99", sdRule{key: "nice"})
		if len(mapped(cfg, "nice")) != 0 || len(cfg.errs) != 0 {
			t.Fatalf("mapped %q errs %q, want nothing", mapped(cfg, "nice"), cfg.errs)
		}
		if len(w) != 1 || w[0].Level != "WARN" || !strings.Contains(w[0].Msg, "Nice=99 ignored") {
			t.Fatalf("warnings %v, want one WARN naming Nice=99", w)
		}
	})

	t.Run("confine: a value slinit refuses refuses the unit", func(t *testing.T) {
		cfg := &SystemdConfig{}
		cfg.applyRule("Service", "Nice", "99", sdRule{key: "nice", class: sdConfine})
		if len(cfg.errs) != 1 || len(mapped(cfg, "nice")) != 0 {
			t.Fatalf("errs %q mapped %q, want one error and nothing mapped", cfg.errs, mapped(cfg, "nice"))
		}
	})

	t.Run("conv: an empty result emits nothing, its warnings remain", func(t *testing.T) {
		cfg := &SystemdConfig{}
		r := sdRule{key: "nice", conv: func(string) (string, []SystemdWarning, error) {
			return "", []SystemdWarning{{"NOTE", "default"}}, nil
		}}
		w := cfg.applyRule("Service", "Nice", "0", r)
		if len(mapped(cfg, "nice")) != 0 || len(w) != 1 {
			t.Fatalf("mapped %q warnings %v", mapped(cfg, "nice"), w)
		}
	})
}

func TestGapWarningLevels(t *testing.T) {
	if w := gapWarning("Service", "PAMName", "login", sdGap{why: "x"}); len(w) != 1 || w[0].Level != "NOTE" {
		t.Errorf("behaviour gap: %v, want one NOTE", w)
	}
	if w := gapWarning("Service", "DeviceAllow", "/dev/null rw", sdGap{confine: true, why: "x"}); len(w) != 1 || w[0].Level != "WARN" {
		t.Errorf("confinement gap: %v, want one WARN", w)
	}
	for _, v := range []string{"", "no", "0", "false", "off"} {
		if w := gapWarning("Service", "PrivateIPC", v, sdGap{confine: true, why: "x"}); len(w) != 0 {
			t.Errorf("PrivateIPC=%q restates the default, got %v", v, w)
		}
	}
}
